exercises.solution:
def ips_suspectes(journal, seuil):
    compte = {}
    for ligne in journal:
        champs = ligne.split()
        if champs[2] == "ECHEC":
            compte[champs[4]] = compte.get(champs[4], 0) + 1
    return sorted(ip for ip, n in compte.items() if n >= seuil)

def compromis(journal, seuil):
    echecs = {}
    comptes = set()
    for ligne in journal:
        date, heure, statut, compte, ip = ligne.split()
        if statut == "ECHEC":
            echecs[ip] = echecs.get(ip, 0) + 1
        elif statut == "SUCCES" and echecs.get(ip, 0) >= seuil:
            comptes.add(compte)
    return sorted(comptes)
